-- creaturesounddata: the retail combat sounds of retail race 25 (tools/races/retail_voices.py): a copy of the model's
-- sound row with the vocal columns replaced (footsteps and the rest stay), then the race's models use it.
-- A model another race also uses keeps its row. Runs after creaturemodeldata (file order)

-- Male: sound_aggro_id 283626, sound_death_id 28822, sound_exertion_id 28828, sound_injury_id 28825
DELETE FROM `creaturesounddata` WHERE `id` = @AlliancePandarenMaleSoundData;
INSERT INTO `creaturesounddata` (`id`, `sound_exertion_id`, `sound_exertion_critical_id`, `sound_injury_id`, `sound_injury_critical_id`, `sound_injury_crushing_blow_id`, `sound_death_id`, `sound_stun_id`, `sound_stand_id`, `sound_footstep_id`, `sound_aggro_id`, `sound_wing_flap_id`, `sound_wing_glide_id`, `sound_alert_id`, `sound_fidget_id_1`, `sound_fidget_id_2`, `sound_fidget_id_3`, `sound_fidget_id_4`, `sound_fidget_id_5`, `sound_custom_attack_id_1`, `sound_custom_attack_id_2`, `sound_custom_attack_id_3`, `sound_custom_attack_id_4`, `npc_sound_id`, `loop_sound_id`, `creature_impact_type`, `sound_jump_start_id`, `sound_jump_end_id`, `sound_pet_attack_id`, `sound_pet_order_id`, `sound_pet_dismiss_id`, `fidget_delay_seconds_min`, `fidget_delay_seconds_max`, `birth_sound_id`, `spell_cast_directed_sound_id`, `submerge_sound_id`, `submerged_sound_id`, `creature_sound_data_id_pet`)
SELECT @AlliancePandarenMaleSoundData, 28828, `sound_exertion_critical_id`, 28825, `sound_injury_critical_id`, `sound_injury_crushing_blow_id`, 28822, `sound_stun_id`, `sound_stand_id`, `sound_footstep_id`, 283626, `sound_wing_flap_id`, `sound_wing_glide_id`, `sound_alert_id`, `sound_fidget_id_1`, `sound_fidget_id_2`, `sound_fidget_id_3`, `sound_fidget_id_4`, `sound_fidget_id_5`, `sound_custom_attack_id_1`, `sound_custom_attack_id_2`, `sound_custom_attack_id_3`, `sound_custom_attack_id_4`, `npc_sound_id`, `loop_sound_id`, `creature_impact_type`, `sound_jump_start_id`, `sound_jump_end_id`, `sound_pet_attack_id`, `sound_pet_order_id`, `sound_pet_dismiss_id`, `fidget_delay_seconds_min`, `fidget_delay_seconds_max`, `birth_sound_id`, `spell_cast_directed_sound_id`, `submerge_sound_id`, `submerged_sound_id`, `creature_sound_data_id_pet`
FROM `creaturesounddata` WHERE `id` = (SELECT `sound_data` FROM `creaturemodeldata` WHERE `id` = (SELECT `cdi`.`model_id` FROM `creaturedisplayinfo` `cdi` JOIN `chrraces` `r` ON `cdi`.`id` = `r`.`male_display_id` WHERE `r`.`id` = @AlliancePandaren));
UPDATE `creaturemodeldata` SET `sound_data` = @AlliancePandarenMaleSoundData WHERE `id` = (SELECT `cdi`.`model_id` FROM `creaturedisplayinfo` `cdi` JOIN `chrraces` `r` ON `cdi`.`id` = `r`.`male_display_id` WHERE `r`.`id` = @AlliancePandaren)
  AND `id` NOT IN (SELECT `cdi`.`model_id` FROM `creaturedisplayinfo` `cdi` JOIN `chrraces` `r` ON `cdi`.`id` IN (`r`.`male_display_id`, `r`.`female_display_id`)
                   WHERE `r`.`id` NOT IN (@AlliancePandaren, @HordePandaren)) -- never another race's model
  AND EXISTS (SELECT 1 FROM `creaturesounddata` WHERE `id` = @AlliancePandarenMaleSoundData); -- the copy above found the model's row

-- Female: sound_aggro_id 283625, sound_death_id 31720, sound_exertion_id 31715, sound_injury_id 31718
DELETE FROM `creaturesounddata` WHERE `id` = @AlliancePandarenFemaleSoundData;
